const reportFields=['period','currency','worked','billable','validated_revenue','validated_cost','margin','invoiced','received','outflows','net_flow'];
let reportEpoch=0,reportQuery=null;
function reportNotice(message){$('report-notice').textContent=message}
function reportReset(){reportEpoch++;reportQuery=null;$('report-rows').replaceChildren();$('report-export').disabled=true;reportNotice('')}
function reportDefaults(){const now=new Date(),local=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;$('report-start').value=local(new Date(now.getFullYear(),now.getMonth(),1));$('report-end').value=local(now)}
reportDefaults();$('report-start').onchange=reportReset;$('report-end').onchange=reportReset;
$('report-form').onsubmit=async e=>{e.preventDefault();reportReset();const t=token,epoch=reportEpoch,q=new URLSearchParams({start:$('report-start').value,end:$('report-end').value});try{const r=await fetch('/api/admin/direction/reporting?'+q,{headers:{Authorization:'Bearer '+t}});const d=await r.json();if(!r.ok)throw Error(d.error);if(!token||token!==t||epoch!==reportEpoch)return;for(const x of d.items){const tr=document.createElement('tr');for(const f of reportFields)tr.append(elem('td',x[f]));$('report-rows').append(tr)}reportQuery=q;$('report-export').disabled=false;reportNotice(d.items.length+' ligne(s) mensuelle(s).')}catch(e){if(epoch===reportEpoch)reportNotice(e.message)}};
$('report-export').onclick=async()=>{if(!reportQuery||!token)return;const t=token,e=reportEpoch,q=new URLSearchParams(reportQuery);q.set('format','csv');try{const r=await fetch('/api/admin/direction/reporting?'+q,{headers:{Authorization:'Bearer '+t}});if(!r.ok)throw Error('Export indisponible.');const blob=await r.blob();if(!token||token!==t||e!==reportEpoch)return;const link=document.createElement('a'),url=URL.createObjectURL(blob);link.href=url;link.download='reporting-'+q.get('start')+'-'+q.get('end')+'.csv';document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);reportNotice('Export préparé.')}catch(e){reportNotice(e.message)}};
$('logout').addEventListener('click',()=>{reportReset();reportDefaults()});
